// Test C++ inference for pt_expt (.pt2) DPA4C models with a latent-charge
// long-range module, which sums over every pair of atoms of a complete
// non-periodic system, and over the images of the cell of a periodic one when
// the module serves periodic systems. Models generated by
// source/tests/infer/gen_dpa4c_long_range.py: uncompressed archives on the
// graph lower, which receives the pair list or the mesh of the cell, and
// compressed archives on the compact canonical lower, which reads the
// positions of the atoms and the cell.
#include <gtest/gtest.h>

#include <cmath>
#include <fstream>
#include <vector>

#include "DeepPot.h"
#include "DeepPotPTExpt.h"
#include "expected_ref.h"
#include "neighbor_list.h"
#include "test_utils.h"

namespace {
constexpr const char* kModelPath =
    "../../tests/infer/deeppot_dpa4c_long_range.pt2";
constexpr const char* kRefPath =
    "../../tests/infer/deeppot_dpa4c_long_range.expected";
constexpr const char* kCompressedModelPath =
    "../../tests/infer/deeppot_dpa4c_long_range_compressed.pt2";
constexpr const char* kCompressedRefPath =
    "../../tests/infer/deeppot_dpa4c_long_range_compressed.expected";
constexpr const char* kPeriodicModelPath =
    "../../tests/infer/deeppot_dpa4c_long_range_periodic.pt2";
constexpr const char* kPeriodicRefPath =
    "../../tests/infer/deeppot_dpa4c_long_range_periodic.expected";
constexpr const char* kPeriodicCompressedModelPath =
    "../../tests/infer/deeppot_dpa4c_long_range_periodic_compressed.pt2";
constexpr const char* kPeriodicCompressedRefPath =
    "../../tests/infer/deeppot_dpa4c_long_range_periodic_compressed.expected";

// The full neighbor list of a non-periodic system within ``rc``: every atom
// is local, so the list holds no ghost.
template <typename VALUETYPE>
std::vector<std::vector<int>> nopbc_nlist(const std::vector<VALUETYPE>& coord,
                                          const double rc) {
  const int natoms = static_cast<int>(coord.size() / 3);
  std::vector<std::vector<int>> nlist(natoms);
  for (int ii = 0; ii < natoms; ++ii) {
    for (int jj = 0; jj < natoms; ++jj) {
      double r2 = 0.;
      for (int dd = 0; dd < 3; ++dd) {
        const double diff = coord[ii * 3 + dd] - coord[jj * 3 + dd];
        r2 += diff * diff;
      }
      if (jj != ii && r2 < rc * rc) {
        nlist[ii].push_back(jj);
      }
    }
  }
  return nlist;
}
}  // namespace

// One reference case of an archive: per-atom energies, forces and virials,
// with the totals the interface returns.
template <class VALUETYPE>
struct LongRangeRef {
  std::vector<VALUETYPE> expected_f;
  double expected_tot_e = 0.;
  std::vector<VALUETYPE> expected_tot_v = std::vector<VALUETYPE>(9, 0.);

  void load(const deepmd_test::ExpectedRef& ref, const char* section) {
    const std::vector<VALUETYPE> atom_e =
        ref.template get<VALUETYPE>(section, "expected_e");
    const std::vector<VALUETYPE> atom_v =
        ref.template get<VALUETYPE>(section, "expected_v");
    expected_f = ref.template get<VALUETYPE>(section, "expected_f");
    for (std::size_t ii = 0; ii < atom_e.size(); ++ii) {
      expected_tot_e += atom_e[ii];
      for (int dd = 0; dd < 9; ++dd) {
        expected_tot_v[dd] += atom_v[ii * 9 + dd];
      }
    }
  }

  void check(double ener,
             const std::vector<VALUETYPE>& force,
             const std::vector<VALUETYPE>& virial,
             double epsilon) const {
    ASSERT_EQ(force.size(), expected_f.size());
    ASSERT_EQ(virial.size(), 9u);
    EXPECT_LT(fabs(ener - expected_tot_e), epsilon);
    for (std::size_t ii = 0; ii < force.size(); ++ii) {
      EXPECT_LT(fabs(force[ii] - expected_f[ii]), epsilon);
    }
    for (int ii = 0; ii < 9; ++ii) {
      EXPECT_LT(fabs(virial[ii] - expected_tot_v[ii]), epsilon);
    }
  }
};

template <class VALUETYPE>
class TestInferDeepPotDpa4cLongRangePtExpt : public ::testing::Test {
 protected:
  std::vector<VALUETYPE> coord = {12.83, 2.56, 2.18, 12.09, 2.87, 2.74,
                                  0.25,  3.32, 1.68, 3.36,  3.00, 1.81,
                                  3.51,  2.51, 2.60, 4.27,  3.22, 1.56};
  std::vector<int> atype = {0, 1, 1, 0, 1, 1};
  std::vector<double> charge_spin_explicit = {1.0, 2.0};
  LongRangeRef<VALUETYPE> ref_default;
  LongRangeRef<VALUETYPE> ref_explicit;

  static deepmd::DeepPot dp;

  static void SetUpTestSuite() {
#if defined(BUILD_PYTORCH) && BUILD_PT_EXPT
    dp.init(kModelPath);
#endif
  }

  void SetUp() override {
#if !defined(BUILD_PYTORCH) || !BUILD_PT_EXPT
    GTEST_SKIP() << "Skip because PyTorch support is not enabled.";
#endif
    deepmd_test::ExpectedRef ref;
    ref.load(kRefPath);
    ref_default.load(ref, "default");
    ref_explicit.load(ref, "explicit");
  }

  static void TearDownTestSuite() { dp = deepmd::DeepPot(); }

  // Computes through the LAMMPS-style entry point, with the full neighbor
  // list of the system and no ghost atom.
  void compute_lmp(double& ener,
                   std::vector<VALUETYPE>& force,
                   std::vector<VALUETYPE>& virial,
                   const std::vector<double>& charge_spin) {
    std::vector<std::vector<int>> nlist_data = nopbc_nlist(coord, dp.cutoff());
    const int nloc = static_cast<int>(atype.size());
    std::vector<int> ilist(nloc), numneigh(nloc);
    std::vector<int*> firstneigh(nloc);
    deepmd::InputNlist inlist(nloc, &ilist[0], &numneigh[0], &firstneigh[0]);
    convert_nlist(inlist, nlist_data);
    dp.compute(ener, force, virial, coord, atype, std::vector<VALUETYPE>(), 0,
               inlist, 0, {}, {}, charge_spin);
  }
};

template <class VALUETYPE>
deepmd::DeepPot TestInferDeepPotDpa4cLongRangePtExpt<VALUETYPE>::dp;

TYPED_TEST_SUITE(TestInferDeepPotDpa4cLongRangePtExpt, ValueTypes);

TYPED_TEST(TestInferDeepPotDpa4cLongRangePtExpt, has_long_range) {
  EXPECT_TRUE(this->dp.has_long_range());
  EXPECT_EQ(this->dp.dim_chg_spin(), 2);
}

TYPED_TEST(TestInferDeepPotDpa4cLongRangePtExpt, standalone_default) {
  using VALUETYPE = TypeParam;
  const double epsilon = std::is_same<VALUETYPE, double>::value ? 1e-8 : 1e-4;
  double ener;
  std::vector<VALUETYPE> force, virial;
  this->dp.compute(ener, force, virial, this->coord, this->atype,
                   std::vector<VALUETYPE>());
  this->ref_default.check(ener, force, virial, epsilon);
}

TYPED_TEST(TestInferDeepPotDpa4cLongRangePtExpt, standalone_explicit) {
  using VALUETYPE = TypeParam;
  const double epsilon = std::is_same<VALUETYPE, double>::value ? 1e-8 : 1e-4;
  double ener;
  std::vector<VALUETYPE> force, virial;
  this->dp.compute(ener, force, virial, this->coord, this->atype,
                   std::vector<VALUETYPE>(), {}, {},
                   this->charge_spin_explicit);
  this->ref_explicit.check(ener, force, virial, epsilon);
}

TYPED_TEST(TestInferDeepPotDpa4cLongRangePtExpt, lmp_nlist_explicit) {
  using VALUETYPE = TypeParam;
  const double epsilon = std::is_same<VALUETYPE, double>::value ? 1e-8 : 1e-4;
  double ener;
  std::vector<VALUETYPE> force, virial;
  this->compute_lmp(ener, force, virial, this->charge_spin_explicit);
  this->ref_explicit.check(ener, force, virial, epsilon);
}

// A module that serves no periodic system rejects a cell.
TYPED_TEST(TestInferDeepPotDpa4cLongRangePtExpt, periodic_box_is_rejected) {
  using VALUETYPE = TypeParam;
  const std::vector<VALUETYPE> box = {13., 0., 0., 0., 13., 0., 0., 0., 13.};
  double ener;
  std::vector<VALUETYPE> force, virial;
  EXPECT_THROW(
      this->dp.compute(ener, force, virial, this->coord, this->atype, box),
      deepmd::deepmd_exception);
}

// The compressed archive folds the charge state into constants, which
// set_charge_spin rewrites: the tables of the descriptor and the total charge
// of the constraint together.
template <class VALUETYPE>
class TestInferDeepPotDpa4cLongRangeCompressedPtExpt : public ::testing::Test {
 protected:
  std::vector<VALUETYPE> coord = {12.83, 2.56, 2.18, 12.09, 2.87, 2.74,
                                  0.25,  3.32, 1.68, 3.36,  3.00, 1.81,
                                  3.51,  2.51, 2.60, 4.27,  3.22, 1.56};
  std::vector<int> atype = {0, 1, 1, 0, 1, 1};
  LongRangeRef<VALUETYPE> ref_default;
  LongRangeRef<VALUETYPE> ref_explicit;
  deepmd::DeepPot dp;

  void SetUp() override {
#if !defined(BUILD_PYTORCH) || !BUILD_PT_EXPT
    GTEST_SKIP() << "Skip because PyTorch support is not enabled.";
#endif
    std::ifstream model_file(kCompressedModelPath);
    if (!model_file.good()) {
      GTEST_SKIP() << "Skip because " << kCompressedModelPath
                   << " was not generated (gen_dpa4c_long_range.py writes it "
                      "on a CUDA device only).";
    }
    dp.init(kCompressedModelPath);
    deepmd_test::ExpectedRef ref;
    ref.load(kCompressedRefPath);
    ref_default.load(ref, "default");
    ref_explicit.load(ref, "explicit");
  }

  void compute_lmp(double& ener,
                   std::vector<VALUETYPE>& force,
                   std::vector<VALUETYPE>& virial) {
    std::vector<std::vector<int>> nlist_data = nopbc_nlist(coord, dp.cutoff());
    const int nloc = static_cast<int>(atype.size());
    std::vector<int> ilist(nloc), numneigh(nloc);
    std::vector<int*> firstneigh(nloc);
    deepmd::InputNlist inlist(nloc, &ilist[0], &numneigh[0], &firstneigh[0]);
    convert_nlist(inlist, nlist_data);
    dp.compute(ener, force, virial, coord, atype, std::vector<VALUETYPE>(), 0,
               inlist, 0);
  }
};

TYPED_TEST_SUITE(TestInferDeepPotDpa4cLongRangeCompressedPtExpt, ValueTypes);

TYPED_TEST(TestInferDeepPotDpa4cLongRangeCompressedPtExpt,
           set_charge_spin_follows_the_state) {
  using VALUETYPE = TypeParam;
  constexpr double epsilon = 1e-4;
  EXPECT_TRUE(this->dp.has_long_range());
  double ener;
  std::vector<VALUETYPE> force, virial;
  this->compute_lmp(ener, force, virial);
  this->ref_default.check(ener, force, virial, epsilon);
  this->dp.set_charge_spin({1.0, 2.0});
  this->compute_lmp(ener, force, virial);
  this->ref_explicit.check(ener, force, virial, epsilon);
  this->dp.set_charge_spin({0.0, 1.0});
  this->compute_lmp(ener, force, virial);
  this->ref_default.check(ener, force, virial, epsilon);
}

// A module that serves periodic systems evaluates a periodic system over the
// images of its cell, through the coordinates and the cell or through the
// neighbor list of a LAMMPS-style call, whose ghost atoms are images, and
// keeps the direct sum of a system without a cell. ``Archive`` selects the
// uncompressed archive on the graph lower or, on a CUDA device, the
// compressed one on the compact canonical lower.
template <class VALUETYPE>
class TestInferDeepPotDpa4cLongRangePeriodicPtExpt : public ::testing::Test {
 protected:
  std::vector<VALUETYPE> coord = {12.83, 2.56, 2.18, 12.09, 2.87, 2.74,
                                  0.25,  3.32, 1.68, 3.36,  3.00, 1.81,
                                  3.51,  2.51, 2.60, 4.27,  3.22, 1.56};
  std::vector<int> atype = {0, 1, 1, 0, 1, 1};
  std::vector<VALUETYPE> box = {13.0, 0.0,  0.0, 0.6, 12.5,
                                0.0,  -0.4, 0.8, 13.5};
  LongRangeRef<VALUETYPE> ref_periodic;
  LongRangeRef<VALUETYPE> ref_cluster;
  deepmd::DeepPot dp;

  void load(const char* model_path, const char* ref_path) {
#if !defined(BUILD_PYTORCH) || !BUILD_PT_EXPT
    GTEST_SKIP() << "Skip because PyTorch support is not enabled.";
#endif
    std::ifstream model_file(model_path);
    if (!model_file.good()) {
      GTEST_SKIP() << "Skip because " << model_path
                   << " was not generated (gen_dpa4c_long_range.py writes the "
                      "compressed archives on a CUDA device only).";
    }
    dp.init(model_path);
    deepmd_test::ExpectedRef ref;
    ref.load(ref_path);
    ref_periodic.load(ref, "periodic");
    ref_cluster.load(ref, "cluster");
  }

  // Computes the periodic system through the LAMMPS-style entry point, with
  // the ghost atoms of the cell, and folds their forces back onto their
  // owners.
  void compute_lmp_periodic(double& ener,
                            std::vector<VALUETYPE>& force,
                            std::vector<VALUETYPE>& virial) {
    std::vector<VALUETYPE> coord_cpy;
    std::vector<int> atype_cpy, mapping;
    std::vector<std::vector<int>> nlist_data;
    _build_nlist<VALUETYPE>(nlist_data, coord_cpy, atype_cpy, mapping, coord,
                            atype, box, static_cast<float>(dp.cutoff()));
    const int nloc = static_cast<int>(atype.size());
    const int nall = static_cast<int>(atype_cpy.size());
    std::vector<int> ilist(nloc), numneigh(nloc);
    std::vector<int*> firstneigh(nloc);
    deepmd::InputNlist inlist(nloc, &ilist[0], &numneigh[0], &firstneigh[0]);
    convert_nlist(inlist, nlist_data);
    inlist.mapping = mapping.data();
    std::vector<VALUETYPE> force_all;
    dp.compute(ener, force_all, virial, coord_cpy, atype_cpy, box, nall - nloc,
               inlist, 0);
    _fold_back<VALUETYPE>(force, force_all, mapping, nloc, nall, 3);
  }

  void check_all(const double epsilon) {
    EXPECT_TRUE(dp.has_long_range());
    double ener;
    std::vector<VALUETYPE> force, virial;
    dp.compute(ener, force, virial, coord, atype, box);
    ref_periodic.check(ener, force, virial, epsilon);
    compute_lmp_periodic(ener, force, virial);
    ref_periodic.check(ener, force, virial, epsilon);
    dp.compute(ener, force, virial, coord, atype, std::vector<VALUETYPE>());
    ref_cluster.check(ener, force, virial, epsilon);
  }
};

TYPED_TEST_SUITE(TestInferDeepPotDpa4cLongRangePeriodicPtExpt, ValueTypes);

TYPED_TEST(TestInferDeepPotDpa4cLongRangePeriodicPtExpt, graph_lower) {
  using VALUETYPE = TypeParam;
  this->load(kPeriodicModelPath, kPeriodicRefPath);
  if (this->IsSkipped()) {
    return;
  }
  this->check_all(std::is_same<VALUETYPE, double>::value ? 1e-8 : 1e-4);
}

TYPED_TEST(TestInferDeepPotDpa4cLongRangePeriodicPtExpt, compact_lower) {
  this->load(kPeriodicCompressedModelPath, kPeriodicCompressedRefPath);
  if (this->IsSkipped()) {
    return;
  }
  this->check_all(1e-4);
}

// A cell without volume marks no system: it is rejected rather than taken as
// a non-periodic one.
TYPED_TEST(TestInferDeepPotDpa4cLongRangePeriodicPtExpt,
           degenerate_cell_is_rejected) {
  using VALUETYPE = TypeParam;
  this->load(kPeriodicModelPath, kPeriodicRefPath);
  if (this->IsSkipped()) {
    return;
  }
  double ener;
  std::vector<VALUETYPE> force, virial;
  EXPECT_THROW(this->dp.compute(ener, force, virial, this->coord, this->atype,
                                std::vector<VALUETYPE>(9, 0.)),
               deepmd::deepmd_exception);
}
